const updateUser = `-- name: UpdateUser :one
UPDATE users
SET
  email = COALESCE(?1, email),
  display_name = COALESCE(?2, display_name),
  photo_url = COALESCE(?3, photo_url),
  github_handle = COALESCE(?4, github_handle),
  admin = ?5,
  whitelisted = ?6,
  updated_at = ?7
WHERE id = ?8
RETURNING id, email, display_name, photo_url, github_handle, admin, whitelisted, created_at, updated_at
`

type UpdateUserParams struct {
	Email        sql.NullString
	DisplayName  sql.NullString
	PhotoUrl     sql.NullString
	GithubHandle sql.NullString
	Admin        bool
	Whitelisted  bool
	Ts           time.Time
	ID           uuid.UUID
}

// UpdateUser is a partial patch on the text fields: every COALESCE leaves
// the column unchanged when the corresponding sqlc.narg parameter is NULL.
// There is no clear-via-empty semantics on the optional text columns; if a
// test needs to null out photo_url or github_handle, recreate the user.
// The boolean fields (admin, whitelisted) are always rewritten -- callers
// merge against the existing row in the service layer.
func (q *Queries) UpdateUser(ctx context.Context, arg UpdateUserParams) (User, error) {
	row := q.db.QueryRowContext(ctx, updateUser,
		arg.Email,
		arg.DisplayName,
		arg.PhotoUrl,
		arg.GithubHandle,
		arg.Admin,
		arg.Whitelisted,
		arg.Ts,
		arg.ID,
	)
	var i User
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.DisplayName,
		&i.PhotoUrl,
		&i.GithubHandle,
		&i.Admin,
		&i.Whitelisted,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

